// Starter projects offered when creating a repository. The KiCad files are generated by scripts/templates/build.py
// from KiCad's own symbol and footprint libraries and checked with kicad-cli; do not edit templates.gen.ts by hand.
import type { RepoTemplateInfo } from '@jumper/shared';
import { TEMPLATE_FILES } from './templates.gen';

const INFO: RepoTemplateInfo[] = [
  {
    id: 'esp32-s3',
    name: 'ESP32-S3 board',
    part: 'ESP32-S3-WROOM-1',
    description: 'Wi-Fi and Bluetooth LE module with USB-C, a 3.3 V regulator, reset and boot buttons.',
    includes: ['ESP32-S3-WROOM-1 module', 'USB-C (native USB)', '3.3 V LDO', 'EN and BOOT buttons', 'I/O header'],
  },
  {
    id: 'stm32',
    name: 'STM32 board',
    part: 'STM32F103C8T6',
    description: 'Cortex-M3 microcontroller with an 8 MHz crystal, SWD header, USB-C and a 3.3 V regulator.',
    includes: ['STM32F103C8T6 (LQFP-48)', '8 MHz crystal', 'SWD header', 'USB-C', '3.3 V LDO', 'Reset button'],
  },
  {
    id: 'rp2040',
    name: 'RP2040 board',
    part: 'RP2040',
    description: 'Dual-core Cortex-M0+ with QSPI flash, a 12 MHz crystal, USB-C and a 3.3 V regulator.',
    includes: ['RP2040 (QFN-56)', 'W25Q QSPI flash', '12 MHz crystal', 'USB-C', '3.3 V LDO', 'BOOTSEL and reset buttons'],
  },
];

export const TEMPLATES: (RepoTemplateInfo & { files: Record<string, string> })[] = INFO.filter((t) => TEMPLATE_FILES[t.id]).map((t) => ({ ...t, files: TEMPLATE_FILES[t.id]! }));

export const templateInfos = (): RepoTemplateInfo[] => TEMPLATES.map(({ files: _files, ...info }) => info);
export const findTemplate = (id: string) => TEMPLATES.find((t) => t.id === id);
